using System;using System.Linq;using System.IO;using System.Globalization;using System.Windows.Forms;
namespace ScoreModern {public sealed partial class Editor {
 bool pendingCommandColors;
 int[] CurrentCommandColors(){var words=(NativePreferences.Read(source).Text("COLOR")??"0 15 0 9").Replace(',',' ').Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries);return new[]{Int32.Parse(words[0]),Int32.Parse(words[1]),Int32.Parse(words[2]),words.Length>3?Int32.Parse(words[3]):9};}
 void ShowCommandColors(){Message(String.Join(" ",CurrentCommandColors().Select(v=>v.ToString(CultureInfo.InvariantCulture))));}
 bool ExecuteOriginalCommandColors(string text){if(mode!=ScreenMode.Main)return false;var fields=text.Split(new[]{' ','\t'},2,StringSplitOptions.RemoveEmptyEntries);if(fields.Length==0||!fields[0].Equals("COL",StringComparison.OrdinalIgnoreCase))return false;var numbers=LayoutNumbers(fields.Length>1?fields[1]:"");if(numbers.Length>4)throw new NotSupportedException("COL extra values need original verification.");if(numbers.Length>0&&BitConverter.ToInt32(BitConverter.GetBytes(numbers[0]),0)!=0||numbers.Length>1&&BitConverter.ToInt32(BitConverter.GetBytes(numbers[1]),0)!=0){ApplyCommandColors(numbers);return true;}pendingCommandColors=true;Message("Enter 4 numbers for foreground/background/text/edit color ->");command.Clear();return true;}
 bool SubmitOriginalCommandColors(string text){if(!pendingCommandColors)return false;var numbers=LayoutNumbers(text);if(numbers.Length>4)throw new NotSupportedException("COL extra values need original verification.");pendingCommandColors=false;command.Clear();ApplyCommandColors(numbers);return true;}
 void ApplyCommandColors(float[] numbers){if(numbers.Length==0||(BitConverter.ToInt32(BitConverter.GetBytes(numbers[0]),0)&Int32.MinValue)!=0){ShowCommandColors();return;}var values=new float[4];Array.Copy(numbers,values,numbers.Length);Func<float,float,bool> same=(a,b)=>BitConverter.ToInt32(BitConverter.GetBytes(a),0)==BitConverter.ToInt32(BitConverter.GetBytes(b),0);if(same(values[0],values[1])||same(values[1],values[2])){Message("");return;}int[] colors=values.Select(v=>(int)CenterWord(v)).ToArray();if(colors.Any(v=>v<0||v>15))throw new NotSupportedException("COL requires DOS colour indices0 to15.");if(!NativeEditCompatibility.ReproduceInvalidStates&&(colors[0]==colors[1]||colors[1]==colors[2])){Message("");return;}if(same(values[3],values[1]))colors[3]=CurrentCommandColors()[3];var old=NativePreferences.Read(source);var copy=new ScorePreferences{Path=old.Path};foreach(var pair in old.Entries)copy.Entries[pair.Key]=new ScorePreference{Name=pair.Value.Name,Value=pair.Value.Value,Line=pair.Value.Line};copy.Issues.AddRange(old.Issues);copy.Entries["COLOR"]=new ScorePreference{Name="COLOR",Value=String.Join(" ",colors.Select(v=>v.ToString(CultureInfo.InvariantCulture)))};NativePreferences.Restore(source,copy);ApplyPreferenceColors();Message("");}
 bool CommandColorsKey(KeyEventArgs key){if(!pendingCommandColors)return false;if(key.KeyCode==Keys.Escape){pendingCommandColors=false;command.Clear();ShowCommandColors();key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
}}
